// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public {
        c = new TimelockController(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes32 role, address account) public {
        // The deployer holds only TIMELOCK_ADMIN_ROLE; PROPOSER/EXECUTOR are unset.
        vm.assume(account != address(this));
        vm.assume(account != address(0));
        vm.assume(role != c.TIMELOCK_ADMIN_ROLE());
        bool granted = c.hasRole(role, account);
        assertTrue(granted == false, "ungranted account must not have role");
    }
}
